//! Additional ACL ACE constructors and descriptor-control helper.
use super::acl::{RtlAcl,RtlAceHeader,RtlSecurityDescriptor};
use super::sid::SidHeader;
use super::network::RtlGuid;
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;const BAD_ACL:i32=0xC0000077u32 as i32;const BAD_SD:i32=0xC0000079u32 as i32;
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_control_security_descriptor(sd:*mut RtlSecurityDescriptor,interest:u16,set:u16)->i32{if sd.is_null()||unsafe{(*sd).revision!=1||(*sd).control&0x8000!=0}{return BAD_SD;}unsafe{(*sd).control=((*sd).control&!interest)|(set&interest);}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_ace_by_type(acl:*const RtlAcl,ty:u8,out:*mut *mut core::ffi::c_void)->i32{if acl.is_null()||out.is_null()||unsafe{(*acl).size<8}{return BAD_ACL;}let a=unsafe{&*acl};let mut off=8usize;for _ in 0..a.ace_count{if off+4>a.size as usize{return BAD_ACL;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return BAD_ACL;}if h.ace_type==ty{unsafe{*out=(acl as *mut u8).add(off) as *mut core::ffi::c_void;}return SUCCESS;}off+=h.ace_size as usize;}unsafe{*out=core::ptr::null_mut();}0xC0000225u32 as i32}
unsafe fn add(acl:*mut RtlAcl,revision:u32,flags:u32,mask:u32,obj:*const RtlGuid,inh:*const RtlGuid,sid:*const SidHeader,ty:u8,success:u8,failure:u8)->i32{if acl.is_null()||sid.is_null()||unsafe{(*acl).size<8}||!(revision==2||revision==4){return INVALID;}let sl=unsafe{super::sid::rtl_length_sid(sid)} as usize;if sl==0{return INVALID;}let object_ace=matches!(ty,5|6|7|8);let mut of=0u32;let mut extra=0usize;if object_ace&&!obj.is_null(){of|=1;extra+=16;}if object_ace&&!inh.is_null(){of|=2;extra+=16;}let base=if object_ace{12usize}else{8usize};let size=(base+extra+sl+3)&!3;let a=unsafe{&mut *acl};let mut off=8usize;for _ in 0..a.ace_count{if off+4>a.size as usize{return BAD_ACL;}let h=unsafe{&*((acl as *const u8).add(off) as *const RtlAceHeader)};if h.ace_size<4||off+h.ace_size as usize>a.size as usize{return BAD_ACL;}off+=h.ace_size as usize;}if off+size>a.size as usize{return SMALL;}let mut af=flags as u8;if ty==2||ty==7{if success!=0{af|=0x40;}if failure!=0{af|=0x80;}}unsafe{let p=(acl as *mut u8).add(off);*(p as *mut RtlAceHeader)=RtlAceHeader{ace_type:ty,ace_flags:af,ace_size:size as u16};*((p.add(4)) as *mut u32)=mask;let mut q=p.add(8);if object_ace{*((p.add(8)) as *mut u32)=of;q=p.add(12);if !obj.is_null(){core::ptr::copy_nonoverlapping(obj as *const u8,q,16);q=q.add(16);}if !inh.is_null(){core::ptr::copy_nonoverlapping(inh as *const u8,q,16);q=q.add(16);}}core::ptr::copy_nonoverlapping(sid as *const u8,q,sl);if size>base+extra+sl{core::ptr::write_bytes(q.add(sl),0,size-base-extra-sl);}}a.ace_count+=1;SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_access_allowed_object_ace(a:*mut RtlAcl,r:u32,f:u32,m:u32,o:*const RtlGuid,i:*const RtlGuid,s:*const SidHeader)->i32{unsafe{add(a,r,f,m,o,i,s,5,0,0)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_access_denied_object_ace(a:*mut RtlAcl,r:u32,f:u32,m:u32,o:*const RtlGuid,i:*const RtlGuid,s:*const SidHeader)->i32{unsafe{add(a,r,f,m,o,i,s,6,0,0)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_audit_access_object_ace(a:*mut RtlAcl,r:u32,f:u32,m:u32,o:*const RtlGuid,i:*const RtlGuid,s:*const SidHeader,success:u8,failure:u8)->i32{unsafe{add(a,r,f,m,o,i,s,7,success,failure)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_audit_access_ace_ex(a:*mut RtlAcl,r:u32,f:u32,m:u32,s:*const SidHeader,success:u8,failure:u8)->i32{unsafe{add(a,r,f,m,core::ptr::null(),core::ptr::null(),s,2,success,failure)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_mandatory_ace(a:*mut RtlAcl,r:u32,f:u32,m:u32,s:*const SidHeader)->i32{unsafe{add(a,r,f,m,core::ptr::null(),core::ptr::null(),s,17,0,0)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_add_process_trust_label_ace(a:*mut RtlAcl,r:u32,f:u32,m:u32,s:*const SidHeader)->i32{unsafe{add(a,r,f,m,core::ptr::null(),core::ptr::null(),s,20,0,0)}}
